  FT["PH-H3858"] = {"id":"PH-H3858","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4897_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"进一步修订第120号联邦法（经第2641号与第3043号共和国法修正）的法案","en":"An Act to Further Amend Commonwealth Act Numbered One Hundred Twenty, as Amended by Republic Act Numbered Twenty-Six Hundred and Forty-One and Republic Act Numbered Thirty Hundred and Forty-Three","orig":"An Act to Further Amend Commonwealth Act Numbered One Hundred Twenty, as Amended by Republic Act Numbered Twenty-Six Hundred and Forty-One and Republic Act Numbered Thirty Hundred and Forty-Three","vi":"Đạo luật sửa đổi thêm Đạo luật Cộng hòa số 2641 như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกพระราชบัญญัติแห่งสาธารณรัฐที่ 2641 ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah lagi Undang-Undang Republik No. 2641 sebagaimana diubah","ms":"Akta meminda lagi Akta Republik No. 2641 sebagaimana dipinda"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4897","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4897_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3858-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two-A of Commonwealth Act Numbered One hundred twenty, as such section was inserted therein by Republic Act Numbered Twenty-six hundred and forty-one and amended by Republic Act Numbered Thirty hundred and forty-three, is hereby amended to read as follows:\n\"Sec. 2-A. The National Power Corporation shall have an authorized capital of three hundred million pesos divided into three million shares having a par value of one hundred pesos each, which shares may not be transferred, negotiated, pledged, mortgaged, or otherwise given as security for the payment of any obligation. The said capital stock shall be subscribed wholly by the Government of the Philippines and shall be paid as follows:\n\"The sum of eighty-two million pesos advanced to the National Power Corporation by the Government of the Philippines pursuant to the provisions of Republic Act Numbered Two hundred sixty-six shall be the paid-in subscription for eight hundred twenty thousand shares of stock of said capital stock;\n\"The surplus of twenty-eight million eight hundred eleven thousand pesos of the National Power Corporation shall be capitalized, and shall also be an additional paid-in subscription of the Government of the Philippines for two hundred eighty-eight thousand and one hundred ten shares of stock of the capital stock; and \"The balance of one hundred eighty-nine million one hundred eighty-nine thousand pesos shall be paid by conversion of the existing bonded indebtedness into equity capital and from surpluses of the Corporation, and in the absence thereof, from bond issue upon request of the National Power Corporation for scientific projects duly approved by the President of the Philippines to wit;\n\"The sum of one hundred thirty-nine million, one hundred eighty-nine thousand pesos corresponding to bonded indebtedness which had been already converted into capital stock, subscribed by the Government of the Philippines, equivalent to paid-in subscription of one million, three hundred ninety-one thousand eight hundred ninety shares of stock.\n\"The remaining sum of fifty million pesos, consisting of the following:\n\"Interests consisting of three million three hundred forty thousand five hundred eighty-seven pesos and sixty-one centavos representing excess interests on the amount of fifty-two million ninety pesos and twenty-seven centavos advanced to the National Power Corporation by virtue of Republic Act Numbered Two hundred and sixty-six;\n\"Thirty-five million five hundred fifty-six thousand one hundred seventy-two pesos and twenty-eight centavos interests that will have accrued up to June thirty, nineteen hundred sixty-seven on the bonded indebtedness of one hundred thirty-nine million one hundred eighty-nine thousand pesos and such interests of the advanced already capitalized; and \"Eleven million one hundred three thousand two hundred forty pesos and eleven centavos from the surpluses of the Corporation shall be paid in subscription of the Government of the Philippines for five hundred thousand shares of stock, which shall be considered as the additional authorized capitalization of the National Power Corporation."}},{"id":"PH-H3858-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p54","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Commonwealth Act Numbered One Hundred Twenty, as Amended by Republic Act Numbered Twenty-Six Hundred and Forty-One and Republic Act Numbered Thirty Hundred and Forty-Three","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3859"] = {"id":"PH-H3859","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4898_1967.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"为村社首长、议员、村社司库与村社秘书提供保险保障并授权为此拨款的法案","en":"An Act Providing Insurance Coverage to Barrio Captains, Councilmen, Barrio Treasurers and Barrio Secretaries, and Authorizing the Appropriation of Funds for the Purpose","orig":"An Act Providing Insurance Coverage to Barrio Captains, Councilmen, Barrio Treasurers and Barrio Secretaries, and Authorizing the Appropriation of Funds for the Purpose"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4898","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4898_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3859-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Every barrio captain and councilman duly elected, and every barrio treasurer and barrio secretary duly appointed and qualified, under existing laws, but only while assuming their respective offices, are automatically covered by life, disability and accident insurance benefits herein provided which the Government Service Insurance Systems shall extend as it is hereby directed to extend."}},{"id":"PH-H3859-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The life of a barrio captain is insured for five thousand pesos while that of a councilman barrio treasurer or barrio secretary is insured for three thousand pesos each."}},{"id":"PH-H3859-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"When a barrio captain, councilman, barrio treasurer or barrio secretary becomes fully and permanently incapacitated or disabled arising out of and in the course of the performance of his duties, the barrio captain shall be paid disability insurance proceeds of three thousand pesos, and the councilman, barrio treasurer of barrio secretary, in the amount of two thousand pesos each. Anyone availing the benefits under this Section cannot benefit from Sections four and five hereof."}},{"id":"PH-H3859-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Should a barrio captain suffer injuries as a result of an accident, he shall be paid accident insurance proceeds as follows:\n(a) For an injury to the brain resulting in the loss of sanity, five thousand pesos;\n(b) For permanent loss of sight in both eyes, five thousand pesos;\n(c) For permanent loss of sense of hearing in both ears, three thousand pesos;\n(d) For permanent loss of sight in one eye, two thousand five hundred pesos;\n(e) For permanent loss of sense of hearing in one ear, one thousand pesos;\n(f) For the loss or destruction of two or more limbs, five thousand pesos;\n(g) For the loss of one limb, two thousand five hundred pesos;\n(h) For the loss or destruction of both of his hands at or above the wrist, three thousand pesos;\n(i) For the loss or destruction of both of his feet at or above the ankle, three thousand pesos;\n(j) For the loss or destruction of one hand at or above the wrist, one thousand five hundred pesos;\n(k) For the loss or destruction of one foot at or above the ankle, one thousand five hundred pesos;\n(l) For the loss or destruction of every thumb or great toe, two hundred pesos;\n(m) For the loss or destruction of every finger or toe, one hundred pesos;\n(n) For any other injury requiring hospitalization of at least forty days, one thousand pesos, and in cases where the hospitalization is less than forty days, at such amount not exceeding nine hundred fifty pesos as determined by the Government Service Insurance System and prescribed in its Rules and Regulations issued pursuant to the provisions of this Act; and\n(o) For any other injury requiring medical attention for at least fifteen days, two hundred pesos, and in cases where the medical attention extended is less than fifteen days, at such amount not exceeding one hundred fifty pesos as determined by the Government Service Insurance System and prescribed in its Rules and Regulations issued pursuant to the provisions of this Act."}},{"id":"PH-H3859-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Should a councilman, barrio treasurer or barrio secretary suffer injuries as a result of an accident, he shall be paid accident insurance proceeds as follows:\n(a) For an injury to the brain resulting in the loss of sanity, three thousand pesos;\n(b) For permanent loss of sight in both eyes, three thousand pesos;\n(c) For permanent loss of sense of hearing in both ears, two thousand pesos;\n(d) For permanent loss of sight in one eye, one thousand five hundred pesos;\n(e) For permanent loss of sense of hearing in one ear, five hundred pesos;\n(f) For the loss or destruction of two or more limbs, three thousand pesos;\n(g) For the loss of one limb, one thousand five hundred pesos;\n(h) For the loss or destruction of both hands at or above the wrist, two thousand pesos;\n(i) For the loss or destruction of one hand at or above the wrist, one thousand pesos;\n(j) For the loss or destruction of one feet at or above the ankle, one thousand pesos;\n(k) For the loss or destruction of every thumb or great toe, one hundred pesos;\n(l) For the loss or destruction of every finger or toe, eighty pesos;\n(m) For any other injury requiring hospitalization of at least forty days, seven hundred pesos and in case where the hospitalization is less than forty days, at such amount not exceeding six hundred fifty pesos as determined by the Government Service Insurance System and prescribed in its Rules and Regulations issued to the provisions of this Act; and\n(n) For any other injury requiring medical attention for at least fifteen days, one hundred pesos, and in cases where the medical attention extended is less than fifteen days, at such amount not exceeding ninety pesos as determined by the Government Service Insurance System and prescribed in its Rules and Regulations pursuant to the provisions of this Act."}},{"id":"PH-H3859-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"For all the insurance benefits provided under this Act, the national government of the Republic of the Philippines shall pay an annual premium to the Government Service Insurance System the sum of fifteen pesos for every barrio captain and the sum of ten pesos for every councilman, barrio treasurer or barrio secretary: Provided, That any failure or delay in the payment of such premiums shall not in any way prejudice the efficacy and enforceability of the insurance benefits herein set forth."}},{"id":"PH-H3859-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"To carry out the purposes of this Act, there is hereby authorized to be appropriated, the amount of two million eight hundred fifty thousand pesos to pay the annual premiums starting upon the approval of this Act. Thereafter, there shall be authorized to be appropriated annually and included in the General Appropriations Act for every subsequent year, out of any funds in the National Treasury not otherwise appropriated, the amount of two million eight hundred fifty thousand pesos or such amount as may be necessary to pay the annual premiums payable by the national government by virtue of this Act as certified to by the Presidential Assistant on Community Development: Provided, That any of such amount not used to pay said premiums shall automatically revert to the general fund."}},{"id":"PH-H3859-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Within one month after the effectivity of this Act. the Government Service Insurance System shall prescribed and promulgate such rules and regulations as may be necessary as to insure the enjoyment of the benefits herein envisioned by the persons concerned."}},{"id":"PH-H3859-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Only to such extent as would affect the enforcement of this Act, all Acts, executive orders, rules and regulations, or a part thereof, inconsistent with this Act, are hereby amended or modified accordingly."}},{"id":"PH-H3859-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p54","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing Insurance Coverage to Barrio Captains, Councilmen, Barrio Treasurers and Barrio Secretaries, and Authorizing the Appropriation of Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
